CREATE TABLE provider_configs(id TEXT PRIMARY KEY, config_json TEXT NOT NULL, credential_version TEXT NOT NULL DEFAULT '', deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)));
CREATE TABLE provider_defaults(kind TEXT PRIMARY KEY CHECK(kind IN ('image','video')), provider_id TEXT NOT NULL REFERENCES provider_configs(id));
CREATE TABLE capabilities(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES provider_configs(id), definition_json TEXT NOT NULL);
CREATE TABLE price_quotes(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), input_hash TEXT NOT NULL, frozen_json TEXT NOT NULL, source TEXT NOT NULL, version TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE questions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), session_id TEXT NOT NULL DEFAULT '', task_id TEXT REFERENCES tasks(id), kind TEXT NOT NULL, source TEXT NOT NULL, revision INTEGER NOT NULL, task_revision INTEGER, input_hash TEXT NOT NULL, quote_id TEXT REFERENCES price_quotes(id), state TEXT NOT NULL, question_json TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE question_receipts(id TEXT PRIMARY KEY, question_id TEXT NOT NULL REFERENCES questions(id), request_id TEXT NOT NULL, actor TEXT NOT NULL CHECK(actor='human'), response_json TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(question_id,request_id));
